-- 213: machine-translated proposal seeds for the NEW locales uk + sv
-- (full client-namespace catalogues, full game-namespace base-game tables),
-- plus the es/ru backfill for 14 keys added since wave 2 (lobby betting,
-- new shop cosmetics, and the re-keyed multilingual language header).
--
-- Same contract as 184/189: PENDING proposals only, sentinel proposer
-- 'claude-mt' so the audit trail shows plainly that a machine wrote them,
-- license_assent TRUE with the machine-translation terms revision. NEW FILE
-- because appending to an applied migration never re-runs (189's header).
--
-- ATOMIC BY CONSTRUCTION (Aug-11 review find 11). The deploy wrapper runs
-- `psql -f` with ON_ERROR_STOP but WITHOUT --single-transaction, so every
-- statement would otherwise autocommit on its own: the 3,928-row INSERT
-- would land and a failing assertion below would then report a failed
-- deploy over already-committed data. The explicit BEGIN/COMMIT makes the
-- wave all-or-nothing however psql is invoked, and the wrapper's `||`
-- retry re-runs the whole file safely because every guard is idempotent.
--
-- Rerunnable: skip a key+language that already has a pending proposal from
-- ANYONE, and skip any (key, language, source revision) this sentinel has
-- EVER proposed regardless of status — moderator decisions stay decided.
--
-- ORDERING: seeds only keys already present in i18n_keys, which
-- tools/i18n_sync_keys.py populates AFTER the API deploy (the deploy must
-- also carry I18N_LANGS uk/sv + the game namespace sync + the named-hole validator rule).
-- On an unsynced database the assertions below RAISE and the transaction
-- rolls back, leaving nothing behind; re-run after the sync.
BEGIN;

-- This wave's exact tuple set. A TEMP table (dropped at COMMIT) so the
-- INSERT and the assertions read the SAME list — the old file asserted a
-- GLOBAL claude-mt/uk/sv count, which a human's pending proposal or any
-- later wave would break (find 12).
CREATE TEMP TABLE _seed213 (
  key_id      VARCHAR(16) NOT NULL,
  lang        VARCHAR(8)  NOT NULL,
  source_hash VARCHAR(40) NOT NULL,
  target      TEXT        NOT NULL
) ON COMMIT DROP;

